def strWithout3a3b(A: int, B: int) -> str:
    result = []
    while A > 0 or B > 0:
        if abs(A - B) >= 2:
            if A > B:
                result.append('aa')
                A -= 2
                if B > 0:
                    result.append('b')
                    B -= 1
            else:
                result.append('bb')
                B -= 2
                if A > 0:
                    result.append('a')
                    A -= 1
        else:
            if A >= B:
                result.append('a')
                A -= 1
                if B > 0:
                    result.append('b') if B > 0 else None
                    B -= 1
            else:
                result.append('b')
                B -= 1
                if A > 0:
                    result.append('a') if A > 0 else None
                    A -= 1
    return ''.join(result)
